{
  "units": [
    {
      "quote_ref": "F002",
      "scope_refs": ["F000"],
      "kind": "definition",
      "meaning": "In this chapter, the term “individualized education program” or “IEP” means a written statement for each child with a disability that is developed, reviewed, and revised in accordance with section 1414 and that includes the required statutory components."
    },
    {
      "quote_ref": "F004",
      "scope_refs": ["F000", "F002", "F003"],
      "kind": "requirement",
      "meaning": "An IEP must include a statement of the child's present levels of academic achievement and functional performance, including how the child’s disability affects the child’s involvement and progress in the general education curriculum."
    },
    {
      "quote_ref": "F005",
      "scope_refs": ["F000", "F002", "F003"],
      "kind": "requirement",
      "meaning": "For preschool children, an IEP must include a statement, as appropriate, of how the disability affects the child’s participation in appropriate activities as part of the child's present levels of academic achievement and functional performance."
    },
    {
      "quote_ref": "F006",
      "scope_refs": ["F000", "F002", "F003"],
      "kind": "requirement",
      "meaning": "For children with disabilities who take alternate assessments aligned to alternate achievement standards, an IEP must include a description of benchmarks or short-term objectives as part of the present levels statement."
    },
    {
      "quote_ref": "F007:F009",
      "scope_refs": ["F000", "F002"],
      "kind": "requirement",
      "meaning": "An IEP must include a statement of measurable annual goals, including academic and functional goals, designed to meet the child’s needs resulting from the disability to enable the child to be involved in and make progress in the general education curriculum, and to meet each of the child’s other educational needs resulting from the disability."
    },
    {
      "quote_ref": "F010",
      "scope_refs": ["F000", "F002"],
      "kind": "requirement",
      "meaning": "An IEP must include a description of how the child’s progress toward meeting the annual goals will be measured, and a description of when periodic reports on the progress the child is making toward meeting those goals (such as through quarterly or other periodic reports concurrent with report cards) will be provided."
    },
    {
      "quote_ref": "F011:F014",
      "scope_refs": ["F000", "F002"],
      "kind": "requirement",
      "meaning": "An IEP must include a statement of the special education and related services and supplementary aids and services (based on peer-reviewed research to the extent practicable) to be provided to the child or on behalf of the child, and a statement of program modifications or supports for school personnel provided for the child to advance appropriately toward attaining annual goals, to be involved and progress in the general education curriculum and participate in extracurricular and nonacademic activities, and to be educated and participate with other children with disabilities and nondisabled children."
    },
    {
      "quote_ref": "F015",
      "scope_refs": ["F000", "F002"],
      "kind": "requirement",
      "meaning": "An IEP must include an explanation of the extent, if any, to which the child will not participate with nondisabled children in the regular class and in the extracurricular and other nonacademic activities described in subclause (IV)(cc)."
    },
    {
      "quote_ref": "F017",
      "scope_refs": ["F000", "F002"],
      "kind": "requirement",
      "meaning": "An IEP must include a statement of any individual appropriate accommodations necessary to measure the academic achievement and functional performance of the child on State and districtwide assessments consistent with section 1412(a)(16)(A)."
    },
    {
      "quote_ref": "F018:F020",
      "scope_refs": ["F000", "F002"],
      "kind": "requirement",
      "meaning": "If the IEP Team determines that the child shall take an alternate assessment on a particular State or districtwide assessment of student achievement, the IEP must include a statement of why the child cannot participate in the regular assessment and why the particular alternate assessment selected is appropriate for the child."
    },
    {
      "quote_ref": "F022",
      "scope_refs": ["F000", "F002"],
      "kind": "requirement",
      "meaning": "An IEP must include the projected date for the beginning of the services and modifications described in subclause (IV), as well as their anticipated frequency, location, and duration."
    },
    {
      "quote_ref": "F024",
      "scope_refs": ["F000", "F002", "F023"],
      "kind": "requirement",
      "meaning": "Beginning not later than the first IEP in effect when the child is 16, and updated annually thereafter, the IEP must include appropriate measurable postsecondary goals based upon age-appropriate transition assessments related to training, education, employment, and, where appropriate, independent living skills."
    },
    {
      "quote_ref": "F025",
      "scope_refs": ["F000", "F002", "F023"],
      "kind": "requirement",
      "meaning": "Beginning not later than the first IEP in effect when the child is 16, and updated annually thereafter, the IEP must include the transition services (including courses of study) needed to assist the child in reaching the postsecondary goals."
    },
    {
      "quote_ref": "F026",
      "scope_refs": ["F000", "F002", "F023"],
      "kind": "requirement",
      "meaning": "Beginning not later than 1 year before the child reaches the age of majority under State law, the IEP must include a statement that the child has been informed of any rights under this chapter that will transfer to the child upon reaching the age of majority under section 1415(m)."
    },
    {
      "quote_ref": "F029",
      "scope_refs": ["F028"],
      "kind": "prohibition",
      "meaning": "Nothing in section 1414 shall be construed to require that additional information be included in a child’s IEP beyond what is explicitly required in this section."
    },
    {
      "quote_ref": "F030",
      "scope_refs": ["F028"],
      "kind": "prohibition",
      "meaning": "Nothing in section 1414 shall be construed to require the IEP Team to include information under one component of a child’s IEP that is already contained under another component of that IEP."
    },
    {
      "quote_ref": "F033",
      "scope_refs": ["F000", "F032"],
      "kind": "definition",
      "meaning": "The individualized education program team (IEP Team) includes the parents of a child with a disability."
    },
    {
      "quote_ref": "F034",
      "scope_refs": ["F000", "F032"],
      "kind": "definition",
      "meaning": "The IEP Team includes not less than 1 regular education teacher of the child, if the child is, or may be, participating in the regular education environment."
    },
    {
      "quote_ref": "F035",
      "scope_refs": ["F000", "F032"],
      "kind": "definition",
      "meaning": "The IEP Team includes not less than 1 special education teacher, or where appropriate, not less than 1 special education provider of the child."
    },
    {
      "quote_ref": "F036:F039",
      "scope_refs": ["F000", "F032"],
      "kind": "definition",
      "meaning": "The IEP Team includes a representative of the local educational agency who is qualified to provide or supervise specially designed instruction for children with disabilities, is knowledgeable about the general education curriculum, and is knowledgeable about the availability of agency resources."
    },
    {
      "quote_ref": "F041",
      "scope_refs": ["F000", "F032"],
      "kind": "definition",
      "meaning": "The IEP Team includes an individual who can interpret the instructional implications of evaluation results, who may be an existing team member described in clauses (ii) through (vi)."
    },
    {
      "quote_ref": "F042",
      "scope_refs": ["F000", "F032"],
      "kind": "definition",
      "meaning": "At the discretion of the parent or the agency, the IEP Team may include other individuals who have knowledge or special expertise regarding the child, including related services personnel as appropriate."
    },
    {
      "quote_ref": "F043",
      "scope_refs": ["F000", "F032"],
      "kind": "definition",
      "meaning": "Whenever appropriate, the IEP Team includes the child with a disability."
    },
    {
      "quote_ref": "F046",
      "scope_refs": [],
      "kind": "exception",
      "meaning": "A member of the IEP Team is not required to attend an IEP meeting, in whole or in part, if the parent of the child with a disability and the local educational agency agree that attendance is not necessary because the member’s area of the curriculum or related services is not being modified or discussed in the meeting."
    },
    {
      "quote_ref": "F048:F050",
      "scope_refs": [],
      "kind": "permission",
      "meaning": "A member of the IEP Team may be excused from attending an IEP meeting, in whole or in part, when the meeting involves a modification to or discussion of the member’s area of the curriculum or related services, if the parent and the local educational agency consent to the excusal and the member submits written input into the development of the IEP to the parent and the IEP Team prior to the meeting."
    },
    {
      "quote_ref": "F053",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "A parent’s agreement to an IEP Team member not attending an IEP meeting under clause (i) and a parent's consent to an IEP Team member excusal under clause (ii) must be in writing."
    },
    {
      "quote_ref": "F056",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "In the case of a child who was previously served under subchapter III, an invitation to the initial IEP meeting shall, at the request of the parent, be sent to the subchapter III service coordinator or other representatives of the subchapter III system to assist with the smooth transition of services."
    }
  ]
}
